securityEventsGraphQL:
query RecentFirewallEvents($zoneTag: string!, $start: Time!, $end: Time!) {
  viewer {
    zones(filter: { zoneTag: $zoneTag }) {
      firewallEventsAdaptive(
        filter: { datetime_geq: $start, datetime_leq: $end }
        limit: 100
        orderBy: [datetime_DESC]
      ) {
        datetime
        action
        source
        ruleId
        rayName
        clientIP
        clientASNDescription
        clientCountryName
        clientRequestHTTPHost
        clientRequestPath
        clientRequestHTTPMethodName
        userAgent
      }
    }
  }
}

# POST https://api.cloudflare.com/client/v4/graphql  (Bearer token: Account Analytics Read)
# variables: { "zoneTag": "<ZONE_ID>", "start": "2026-06-16T00:00:00Z", "end": "2026-06-17T00:00:00Z" }
# To aggregate counts by action+source instead of raw events, use the firewallEventsAdaptiveGroups
# dataset: firewallEventsAdaptiveGroups(filter: {...}, limit: 100) { count dimensions { action source clientRequestHTTPHost } }
